              ["DriveDreamer-2 \u7f16\u53f7 2403.06846", "\u8be5\u7f16\u53f7\u5b9e\u4e3a DiaLoc \u4e00\u6587\uff1b\u6b63\u786e\u7f16\u53f7\u662f 2403.06845\uff0c\u4e14\u5df2\u4e3a AAAI-25 \u6b63\u5f0f\u8bba\u6587", "AAAI OJS \u4e0e arXiv \u4e24\u4e2a\u6761\u76ee"],
              ["ISO 26262 \u6807\u6ce8", "68383 \u53ea\u662f Part 1\uff082018\uff09\uff0c\u7cfb\u5217\u5171 12 \u4e2a part", "ISO \u6807\u51c6\u8bb0\u5f55\u4e0e AFNOR \u6807\u51c6\u9875"],
              ["Neural Circuit Policies \u7684 arXiv \u94fe\u63a5", "\u8be5\u94fe\u63a5\u6307\u5411\u53e6\u4e00\u7bc7\u5b8c\u5168\u4e0d\u540c\u7684\u8bba\u6587", "Crossref DOI \u5143\u6570\u636e\u4e0e ISTA \u673a\u6784\u5e93"],
