    para(doc, "\u53e6\u4e00\u4e2a\u8981\u8bf4\u6e05\u695a\u7684\u662f\u6570\u636e\u89c4\u6a21\u3002\u8bba\u6587\u62a5\u544a\u7684\u6709\u6548\u6837\u672c\u662f\u9ad8\u901f\u516c\u8def 3594 \u7ec4\u3001\u57ce\u5e02\u9053\u8def 4846 \u7ec4\uff1b\u6309\u56db\u7c7b\u5de5\u51b5\u5212\u5206\u540e\uff0c\u524d\u65b9\u65e0\u8f66 3500 \u7ec4\u3001\u76f8\u90bb\u8f66\u9053\u8f66\u8f86\u63d2\u5165 750 \u7ec4\u3001\u524d\u65b9\u8f66\u8f86\u51cf\u901f 3390 \u7ec4\u3001\u524d\u65b9\u8f66\u8f86\u9a76\u79bb 800 \u7ec4\u3002\u91c7\u96c6\u8bbe\u5907\u662f\u5927\u9646 ARS408 \u6beb\u7c73\u6ce2\u96f7\u8fbe\uff08\u6d4b\u901f\u7cbe\u5ea6 \u00b10.1 km/h\uff09\u3001M8030 GPS \u6a21\u5757\u3001HEX-V2 CAN \u603b\u7ebf\u5206\u6790\u4eea\u3002\u9ad8\u901f\u8bd5\u9a8c\u5728\u5409\u53cc\u9ad8\u901f\uff08G1112\uff09\u5b8c\u6210\uff0c\u4ee5 60\u300180\u3001100\u3001120 km/h \u56db\u79cd\u521d\u59cb\u8f66\u901f\u5404\u8dd1\u7ea6\u4e00\u5c0f\u65f6\uff0c\u4e14\u5747\u5728\u6674\u5929\u3001\u4fdd\u6301\u4e2d\u95f4\u8f66\u9053\u3002\u8fd9\u4e9b\u7ec6\u8282\u51b3\u5b9a\u4e86\u6211\u4eec\u80fd\u58f0\u79f0\u4ec0\u4e48\u8303\u56f4\u5185\u7684\u7ed3\u8bba\uff1a\u5929\u6c14\u4e0d\u597d\u3001\u4ea4\u53c9\u53e3\u3001\u57ce\u5e02\u666e\u901a\u9053\u8def\u90fd\u4e0d\u5728\u8986\u76d6\u8303\u56f4\u5185\u3002")

