    para(doc, "\u7ed3\u679c\u5951\u7ea6\u8fd9\u4ef6\u4e8b\u770b\u7740\u50cf\u884c\u653f\u5de5\u4f5c\uff0c\u5b9e\u9645\u4e0a\u662f\u4e3a\u4e86\u9632\u4e00\u4e2a\u5e38\u89c1\u95ee\u9898\uff1a\u6570\u636e\u8dd1\u51fa\u6765\u4ee5\u540e\uff0c\u56e0\u4e3a\u6ca1\u6709\u56fa\u5b9a\u7684\u5b58\u50a8\u683c\u5f0f\u4e0e\u547d\u540d\u89c4\u5219\uff0c\u5bfc\u81f4\u7a3f\u5b50\u91cc\u7684\u6570\u5b57\u56de\u6eaf\u4e0d\u5230\u5177\u4f53\u6587\u4ef6\u3002\u6211\u4eec\u628a\u7ed3\u679c\u6587\u4ef6\u7684\u547d\u540d\u5b9a\u4e3a\u201c\u8bba\u6587_\u5b9e\u9a8c_\u573a\u666f_\u79cd\u5b50\u96c6\u201d\u56db\u6bb5\uff0c\u5e76\u8981\u6c42\u6bcf\u4efd\u7ed3\u679c\u5fc5\u586b 14 \u4e2a\u5b57\u6bb5\uff0c\u5176\u4e2d\u5305\u62ec\u79cd\u5b50\u5217\u8868\u3001\u914d\u7f6e\u6587\u4ef6\u7684\u54c8\u5e0c\u3001\u8bc1\u636e\u6765\u6e90\u662f\u81ea\u5df1\u8dd1\u7684\u8fd8\u662f\u5f15\u7528\u522b\u4eba\u7684\u3001\u4ee5\u53ca\u653e\u5f03\u8fc7\u7684\u8bbe\u5b9a\u3002\u81ea\u68c0\u4ea7\u7269\u4e0e\u6b63\u5f0f\u7ed3\u679c\u5206\u5f00\u5b58\u653e\uff0c\u907f\u514d\u8c03\u8bd5\u6570\u636e\u6df7\u8fdb\u7a3f\u5b50\u3002")

