    heading(doc, "7.1 \u7b97\u529b", 2)
    para(doc, "\u672c\u673a\u6ca1\u6709\u53ef\u7528 GPU\uff0cCARLA \u95ed\u73af\u8bad\u7ec3\u4e0e\u5927\u89c4\u6a21\u6d88\u878d\u76ee\u524d\u8dd1\u4e0d\u4e86\u3002\u6211\u7684\u5904\u7406\u529e\u6cd5\u662f\u628a\u5de5\u4f5c\u5206\u6210\u4e24\u7c7b\uff1a\u516c\u5f0f\u590d\u73b0\u3001\u89c4\u5219\u590d\u73b0\u3001\u7edf\u8ba1\u811a\u672c\u3001\u53c2\u8003\u6587\u732e\u5e93\u8fd9\u4e9b\u7eaf CPU \u7684\u4e8b\u60c5\u7acb\u5373\u505a\uff1bCARLA \u76f8\u5173\u7684\u4e00\u5f8b\u5f80\u540e\u653e\uff0c\u7b49\u7b97\u529b\u6709\u7740\u843d\u518d\u542f\u52a8\u3002\u8fd9\u6837\u5b89\u6392\u7684\u597d\u5904\u662f\u65e0\u8bba\u7b97\u529b\u4ec0\u4e48\u65f6\u5019\u5230\u4f4d\uff0c\u524d\u7f6e\u90e8\u5206\u90fd\u4e0d\u4f1a\u767d\u7b49\u3002")

    heading(doc, "7.2 \u6570\u636e", 2)
    para(doc, "\u5b9e\u8f66\u6570\u636e\u96c6\u4e0e TD3 \u4ee3\u7801\u90fd\u4e0d\u5728\u6211\u4eec\u624b\u4e0a\u3002\u5bf9\u524d\u8005\uff0c\u6211\u5df2\u7ecf\u628a\u7533\u8bf7\u4fe1\u5199\u597d\uff0c\u7b56\u7565\u662f\u5148\u7d22\u53d6\u201c\u91cd\u7b97 OTF \u6240\u9700\u7684\u6700\u5c0f\u5b57\u6bb5\u96c6\u201d\uff0c\u5e76\u4e14\u660e\u786e\u63a5\u53d7\u53ea\u63d0\u4f9b\u805a\u5408\u7edf\u8ba1\u91cf\u7684\u964d\u7ea7\u65b9\u6848\uff0c\u4ee5\u63d0\u9ad8\u6210\u529f\u7387\u3002\u5bf9\u540e\u8005\uff0c\u8bba\u6587\u7b2c 5 \u7ae0\u628a actor \u4e0e critic \u7684\u5c42\u6570\u3001\u795e\u7ecf\u5143\u4e2a\u6570\u3001\u5b66\u4e60\u7387\u3001\u4f18\u5316\u5668\u3001\u68af\u5ea6\u9608\u503c\u4e0e\u6b63\u5219\u5316\u7cfb\u6570\u90fd\u7ed9\u51fa\u4e86\uff0c\u6309\u8868 5.1 \u4e0e 5.2 \u91cd\u5b9e\u73b0\u6280\u672f\u4e0a\u53ef\u884c\uff1b\u4f46\u5728\u7a3f\u4ef6\u91cc\u5fc5\u987b\u5199\u6e05\u695a\u57fa\u7ebf\u5230\u5e95\u662f\u201c\u5f15\u7528\u539f\u5b9e\u73b0\u201d\u8fd8\u662f\u201c\u6211\u4eec\u590d\u73b0\u201d\uff0c\u4e24\u8005\u4e0d\u80fd\u6df7\u3002\u6211\u503e\u5411\u73b0\u5728\u5148\u6309\u201c\u5f15\u7528\u201d\u5904\u7406\uff0c\u7b49\u6709\u7b97\u529b\u518d\u51b3\u5b9a\u662f\u5426\u91cd\u5b9e\u73b0\u3002")

    heading(doc, "7.3 \u4eff\u771f\u73af\u5883\u4ece\u96f6\u5efa", 2)
    para(doc, "\u5b66\u4f4d\u8bba\u6587\u6ca1\u6709\u7528 CARLA\uff0c\u6240\u4ee5\u5efa\u56fe\u3001\u4ea4\u901a\u6d41\u3001\u5730\u56fe\u4fee\u6539\u90fd\u9700\u8981\u81ea\u5df1\u505a\u3002\u8fd9\u662f\u4e00\u5757\u5bb9\u6613\u88ab\u4f4e\u4f30\u7684\u5de5\u4f5c\u91cf\uff0c\u6211\u628a\u5b83\u5355\u72ec\u5217\u51fa\u6765\uff0c\u4e0d\u5f80\u201c\u73af\u5883\u642d\u5efa\u201d\u91cc\u585e\u3002")

    heading(doc, "7.4 \u5f15\u7528\u4e0e\u7248\u672c\u98ce\u9669", 2)
